<?php
defined( 'ABSPATH' ) || exit;
class AMANAH_SEO_AI_Article_Package_Validator {
	public function validate($package){ if(!is_array($package))return new WP_Error('invalid_article_package','Article Package must be an object.'); foreach(array('article','media_plan','image_metadata','publishing_metadata','internal_linking_plan') as $key){if(!array_key_exists($key,$package))return new WP_Error('article_package_missing_field','Article Package is missing: '.$key.'.');} if(!is_array($package['article'])||empty($package['article']['title'])||empty($package['article']['body']))return new WP_Error('article_package_invalid_article','Article content is incomplete.'); if(isset($package['publishing_metadata']['author_id'])&&$package['publishing_metadata']['author_id']&&!get_user_by('id',absint($package['publishing_metadata']['author_id'])))return new WP_Error('article_package_invalid_author','Author reference is invalid.'); foreach((array)$package['internal_linking_plan'] as $link){if(!is_array($link))return new WP_Error('article_package_invalid_link','Internal link item is invalid.');if(!empty($link['target_url'])&&!wp_http_validate_url($link['target_url']))return new WP_Error('article_package_invalid_url','Internal link URL is invalid.');} return true; }
}